/*
** My participation to Genuary 2025
** https://genuary.art/
** Prompt of the day : Isometric Art (No vanishing points).
*/

#define sat(a) clamp(a, 0., 1.)
#define rot(a) mat2(cos(a), -sin(a), sin(a), cos(a))
#define PI acos(-1.)
vec2 _min(vec2 a, vec2 b)
{
    if (a.x < b.x)
        return a;
    return b;
}

float _sqr(vec2 uv, vec2 s)
{
    vec2 l = abs(uv)-s;
    return max(l.x, l.y);
}

float _cube(vec3 p, vec3 s)
{
    vec3 l = abs(p)-s;
    return max(l.x, max(l.y, l.z));
}

float _cucube(vec3 p, vec3 s, vec3 th)
{
    float c = _cube(p, s);

    c = max(c, -_sqr(p.xy, s.xy-th.xy));
    c = max(c, -_sqr(p.yz, s.yz-th.yz));
    c = max(c, -_sqr(p.xz, s.xy-th.xz));
    return c;
}

vec2 map(vec3 p)
{
    float repx = 3.5;
    float id = floor((p.x+repx*.5)/repx);
    p.x = mod(p.x+repx*.5,repx)-repx*.5;
    vec2 acc = vec2(1000.,-1.);
    float t = iTime+id;
    p.z += sin(id+iTime*.5)+2.*sin(3.*id+iTime*.15);
    p.y += +abs(sin(t*2.))*.4;
    p.yz *= rot(t);
    float cube = _cucube(p, vec3(1.), vec3(.02));
    acc = _min(acc, vec2(cube, 1.));

    return acc;
}

vec3 getNorm(vec3 p)
{
    vec2 e = vec2(0.01,0.);
    float d = map(p+e.xxx).x;
    return normalize(vec3(d)-vec3(
        map(p-e.xyy).x,
        map(p-e.yxy).x,
        map(p-e.yyx).x));
}
float linesrep(vec2 uv)
{
    float rep = .05;
    uv.y = mod(uv.y+rep*.5, rep)-rep*.5;
    return abs(uv.y)-0.00001;
}
vec3 lines(vec2 uv)
{
    uv *= rot(.5*PI/3.);
    vec3 col = mix(vec3(0.99, 0.99, 0.99), vec3(0.99, 0.99, 0.99)*.75, pow(1.-sat(length(uv)*1.5),.5));
    uv += -iTime*.058*vec2(.5,1.);
    for (float i = 0.; i < 3.; ++i)
    {
        uv *= rot(PI/3.);
        float l = linesrep(uv);
        col =mix(col, vec3(0.), (1.-sat(l*iResolution.x*.6))*.1);    
    }
    return col;
}

vec3 getCam(vec3 ro, vec3 rd, vec2 uv)
{
    vec3 r = normalize(cross(rd, vec3(0.,1.,0.)));
    vec3 u = normalize(cross(rd, r));
    return ro+(r*uv.x+u*uv.y)*20.;
}

vec3 rdr(vec2 uv)
{
    vec3 col = lines(uv);
    //uv *= rot(-PI/3.);
    vec3 ro = vec3(10.,10.,-10.);
    vec3 ta = vec3(0.);
    vec3 rd = normalize(ta-ro);
    ro = getCam(ro, rd, uv);
    vec3 p = ro;
    vec3 acc = vec3(0.);
    for (int i = 0; i < 128; ++i)
    {
        vec2 res = map(p);
        if (distance(p, ro) > 30.)
            break;
        if (res.x < 0.01)
        {
            col *= mix(0.6,0.2,texture(iChannel0, uv*.1).x);
            break;
        }
        p+= rd * res.x*.25;
    }
    col += acc;
    return col;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.xx;
    uv -= texture(iChannel0, uv).x*.002;
    vec3 col = rdr(uv);

    fragColor = vec4(col,1.0);
}
